 * The version of the Azure VoiceLive SDK.
 * Keep this in sync with the `version` field in package.json.
 *
 * @internal
 */
export const SDK_VERSION = "1.1.1";

/**
 * The default API version used by the Voice Live service when the user does
 * not explicitly specify one.
 *
 * @internal
 */
export const DEFAULT_API_VERSION = "2026-07-15";

